'&gt;&gt;&gt; resp.json(){'args': {}, 'data': '', 'files': {}, 'form': {'name1': 'value1', 'name2': 'value2'}, 'headers': {'Accept': '*/*', 'Accept-Encoding': 'gzip, deflate', 'Content-Length': '25', 'Content-Type': 'application/x-www-form-urlencoded', 'Host': 'httpbin.org', 'Spam': 'Eggs', 'User-Agent': 'none/ofyourbusiness', 'X-Amzn-Trace-Id': 'Root=1-62708080-7a14319e699baa2e35a352fb'}, 'json': None, 'origin': '39.154.13.139', 'url': 'http://httpbin.org/post'}&gt;&gt;&gt; requests 模块支持很多种数据的返会方式，可以直接返回以 Unicode 解码的响应文本,也可以返回JSON数据 利用 requests 库发起一个 HEAD 请求 12345678910111213141516&gt;&gt;&gt; import requests&gt;&gt;&gt; resp = requests.head( 'http://httpbin.org/post')&gt;&gt;&gt; resp&lt;Response [405]&gt;&gt;&gt;&gt; resp = requests.head( 'http://httpbin.org/')&gt;&gt;&gt; resp&lt;Response [200]&gt;&gt;&gt;&gt; resp.status_code200&gt;&gt;&gt; resp.headers['content-length']'9593'&gt;&gt;&gt; resp.headers['content-type']'text/html; charset=utf-8'&gt;&gt;&gt; resp.text''&gt;&gt;&gt; 如果决定坚持使用标准的程序库而不考虑像requests这样的第三方库，可以使用底层的 http.client 模块来实现自己的代码。 12345678910from http.client import HTTPConnectionfrom urllib import parsec = HTTPConnection('www.python.org', 80)c.request('HEAD', '/index.html')resp = c.getresponse()print('Status', resp.status)for name, value in resp.getheaders(): print(name, value) 测试 HTTP 客户端,考虑使用httpbin服务(http://httpbin.org)。这个站点会接收发出的请求，然后以JSON 的形式将相应信息回传回来。 1234567&gt;&gt;&gt; import requests&gt;&gt;&gt; r = requests.get('http://httpbin.org/get?name=Dave&amp;n=37',... headers = { 'User-agent': 'goaway/1.0' })&gt;&gt;&gt; resp = r.json()&gt;&gt;&gt; resp['headers']{'Accept': '*/*', 'Accept-Encoding': 'gzip, deflate', 'Host': 'httpbin.org', 'User-Agent': 'goaway/1.0', 'X-Amzn-Trace-Id': 'Root=1-62708c06-7c7d8cc4441479c65faea5b4'}&gt;&gt;&gt; 通过XML-RPC实现简单的远程调用RPC,通俗的讲，想找到一个方式去运行在远程机器上面的 Python 程序中的函数或方法。 实现一个远程方法调用的最简单方式是使用 XML-RPC。下面实现了键 值存储功能的简单RPC服务器： 12345678910111213141516171819202122232425262728293031323334353637383940414243444546#!/usr/bin/env python# -*- encoding: utf-8 -*-&quot;&quot;&quot;@File : app.py@Time : 2022/05/03 17:07:02@Author : Li Ruilong@Version : 1.0@Contact : 1224965096@qq.com@Desc : None&quot;&quot;&quot;# here put the import libfrom xmlrpc.server import SimpleXMLRPCServerclass KeyValueServer: _rpc_methods_ = ['get', 'set', 'delete', 'exists', 'keys'] def __init__(self, address): self._data = {} self._serv = SimpleXMLRPCServer(address, allow_none=True) # 注册方法 for name in self._rpc_methods_: self._serv.register_function(getattr(self, name)) def get(self, name): return self._data[name] def set(self, name, value): self._data[name] = value def delete(self, name): del self._data[name] def exists(self, name): return name in self._data def keys(self): return list(self._data) def serve_forever(self): self._serv.serve_forever() # Exampleif __name__ == '__main__': kvserv = KeyValueServer(('', 15001)) kvserv.serve_forever() RPC客户端测试 1234567891011121314151617PS E:\docker&gt; pythonPython 3.9.0 (tags/v3.9.0:9cf6752, Oct 5 2020, 15:23:07) [MSC v.1927 32 bit (Intel)] on win32Type &quot;help&quot;, &quot;copyright&quot;, &quot;credits&quot; or &quot;license&quot; for more information.&gt;&gt;&gt; from xmlrpc.client import ServerProxy&gt;&gt;&gt; s = ServerProxy('http://localhost:15001', allow_none=True)&gt;&gt;&gt; s.set('foo','bar')&gt;&gt;&gt; s.set('spam', [1, 2, 3])&gt;&gt;&gt; s.keys()['foo', 'spam']&gt;&gt;&gt; s.get('foo')'bar'&gt;&gt;&gt; s.get('spam')[1, 2, 3]&gt;&gt;&gt; s.delete('spam')&gt;&gt;&gt; s.exists('spam')False&gt;&gt;&gt; XML-RPC 可以让很容易的构造一个简单的远程调用服务。所需要做的仅仅是创建一个服务器实例，通过它的方法register_function()来注册函数，然后使用方法serve_forever()启动它。在上面将这些步骤放在一起写到一个类中 这并不是必须的。还可以像下面这样创建一个服务器： 12345678from xmlrpc.server import SimpleXMLRPCServerfrom xmlrpc.server import SimpleXMLRPCServerdef add(x,y): return x+yserv = SimpleXMLRPCServer(('', 15000))serv.register_function(add)serv.serve_forever() XML-RPC 暴露出来的函数只能适用于部分数据类型，比如字符串、整形、列表和字典,不应该将 XML-RPC 服务以公共 API 的方式暴露出来。 XML-RPC 的一个缺点是它的性能。SimpleXMLRPCServer 的实现是单线程的，所以它不适合于大型程序 由于 XML-RPC 将所有数据都序列化为 XML 格式，所以它会比其他的方式运行的慢一些。但是它也有优点，这种方式的编码可以被绝大部分其他编程语言支持。通过使用这种方式，其他语言的客户端程序都能访问的服务。 通过 multiprocessing 实现RPC调用在一个消息传输层如 sockets、multiprocessing.connections或zeroMQ的基础之上实现一个简单的远程过程调用(RPC) 将函数请求、参数和返回值使用pickle编码后，在不同的解释器直接传送pickle字节字符串，可以很容易的实现RPC。下面是一个简单的PRC处理器，可以被整合到一个服务器中去： RPC 服务端 1234567891011121314151617181920212223242526272829303132333435363738394041424344454647484950515253545556575859606162636465666768697071727374757677787980818283848586878889909192939495969798#!/usr/bin/env python# -*- encoding: utf-8 -*-&quot;&quot;&quot;@File : rpcserver.py@Time : 2022/07/08 20:16:21@Author : Li Ruilong@Version : 1.0@Contact : 1224965096@qq.com@Desc : 远程调用服务&quot;&quot;&quot;# here put the import libimport picklefrom multiprocessing.connection import Listenerfrom threading import Thread&quot;&quot;&quot;@Time : 2022/07/08 20:28:02@Author : Li Ruilong@Version : 1.0@Desc : None Args: 远程调用处理器 Returns: void&quot;&quot;&quot;class RPCHandler: def __init__(self): self._functions = {} &quot;&quot;&quot; @Time : 2022/07/08 20:16:47 @Author : Li Ruilong @Version : 1.0 @Desc : 函数注册 Args: func Returns: void &quot;&quot;&quot; def register_function(self, func): self._functions[func.__name__] = func &quot;&quot;&quot; @Time : 2022/07/08 20:17:51 @Author : Li Ruilong @Version : 1.0 @Desc : 调用函数 Args: connection Returns: void &quot;&quot;&quot; def handle_connection(self, connection): try: while True: func_name, args, kwargs = pickle.loads(connection.recv()) try: print(&quot;调用函数：&quot;,(func_name, args, kwargs)) r = self._functions[func_name](*args,**kwargs) print(&quot;返回结果：&quot;,r) connection.send(pickle.dumps(r)) except Exception as e: connection.send(pickle.dumps(e)) except Exception as e: passdef rpc_server(handler, address, authkey): sock = Listener(address, authkey=authkey) while True: client = sock.accept() t = Thread(target=handler.handle_connection, args=(client,)) t.daemon = True print(&quot;函数开始执行&quot;) t.start()def add(x, y): return x + ydef sub(x, y): return x - yif __name__ == '__main__': print(format(&quot;开始加载RPC处理器&quot;,'》&lt;20')) handler = RPCHandler() print(format(&quot;处理器加载完成，注册函数&quot;,'》&lt;20')) handler.register_function(add) handler.register_function(sub) print(format(&quot;函数注册成功,服务启动&quot;,'》&lt;20')) rpc_server(handler, ('localhost', 17000), authkey=b'peekaboo') RPC 客户端 1234567891011121314151617181920212223242526272829import picklefrom multiprocessing.connection import Clientclass RPCProxy: def __init__(self, connection): self._connection = connection def __getattr__(self, name): print(&quot;开始调用函数&quot;,name) def do_rpc(*args, **kwargs): self._connection.send(pickle.dumps((name, args, kwargs))) result = pickle.loads(self._connection.recv()) print(&quot;返回结果&quot;,result) if isinstance(result, Exception): raise result return result return do_rpcc = Client(('localhost', 17000), authkey=b'peekaboo')print(format(&quot;建立连接，创建RPC代理&quot;,'》&lt;30'),c)proxy = RPCProxy(c)print(format(&quot;创建代理成功&quot;,'》&lt;30'))print(&quot;add(2, 3) = &quot;,proxy.add(2, 3) )print(&quot;sub(2, 3) = &quot;, proxy.sub(2, 3)) 1234567891011121314151617181920212223D:\python\Python310\python.exe D:/python/code/rabbit_mq_demo/rpcserver.py开始加载RPC处理器》》》》》》》》》》处理器加载完成，注册函数》》》》》》》》函数注册成功,服务启动》》》》》》》》》函数开始执行调用函数： ('add', (2, 3), {})返回结果： 5调用函数： ('sub', (2, 3), {})返回结果： -1==============D:\python\Python310\python.exe D:/python/code/rabbit_mq_demo/RPC.py建立连接，创建RPC代理》》》》》》》》》》》》》》》》》》 &lt;multiprocessing.connection.Connection object at 0x00DFACA0&gt;创建代理成功》》》》》》》》》》》》》》》》》》》》》》》》开始调用函数 add返回结果 5add(2, 3) = 5开始调用函数 sub返回结果 -1sub(2, 3) = -1Process finished with exit code 0 RPCHandler和RPCProxy的基本思路是很比较简单的。 如果一个客户端想要调用一个远程函数，比如foo(1，2，z=3)，代理类创建一个包含了函数名和参数的元组(foo’，(1，2)，{‘z’：3})。这个元组被 pickle 序列化后通过网络连接发生出去。 由于底层需要依赖 pickle，那么安全问题就需要考虑了(因为一个聪明的黑客可以创建特定的消息，能够让任意函数通过 pickle反序列化后被执行)。 因此永远不要允许来自不信任或未认证的客户端的RPC。特别是绝对不要允许来自Internet的任意机器的访问，这种只能在内部被使用，位于防火墙后面并且不要对外暴露。 作为pickle的替代，也许可以考虑使用JSON、XML或一些其他的编码格式来序列化消息。 例如，本机实例可以很容易的改写成JSON编码方案。还需要将pickle.1oads()和pickle.dumps()替换成json.1oads()和json.dumps()即可： 123456789101112131415161718192021# here put the import libimport json........ def handle_connection(self, connection): try: while True: # 反序列化 func_name, args, kwargs = json.loads(connection.recv()) try: print(&quot;调用函数：&quot;,(func_name, args, kwargs)) r = self._functions[func_name](*args,**kwargs) print(&quot;返回结果：&quot;,r) # 序列化发送 connection.send(json.dumps(r)) except Exception as e: connection.send(json.dumps(e)) except Exception as e: pass...... 1234567891011121314151617181920212223242526272829import jsonfrom multiprocessing.connection import Clientclass RPCProxy: def __init__(self, connection): self._connection = connection def __getattr__(self, name): print(&quot;开始调用函数&quot;,name) def do_rpc(*args, **kwargs): print(&quot;JSON 序列化后的值&quot;,json.dumps((name, args, kwargs))) self._connection.send(json.dumps((name, args, kwargs))) result = json.loads(self._connection.recv()) print(&quot;返回结果&quot;,result) if isinstance(result, Exception): raise result return result return do_rpcc = Client(('localhost', 17000), authkey=b'peekaboo')print(format(&quot;建立连接，创建RPC代理&quot;,'》&lt;30'),c)proxy = RPCProxy(c)print(format(&quot;创建代理成功&quot;,'》&lt;30'))print(&quot;add(2, 3) = &quot;,proxy.add(2, 3) )print(&quot;sub(2, 3) = &quot;, proxy.sub(2, 3)) 可以看到序列化后的结果 1234567891011D:\python\Python310\python.exe D:/python/code/rabbit_mq_demo/RPC.py建立连接，创建RPC代理》》》》》》》》》》》》》》》》》》 &lt;multiprocessing.connection.Connection object at 0x0078AD30&gt;创建代理成功》》》》》》》》》》》》》》》》》》》》》》》》开始调用函数 addJSON 序列化后的值 [&quot;add&quot;, [2, 3], {}]返回结果 5add(2, 3) = 5开始调用函数 subJSON 序列化后的值 [&quot;sub&quot;, [2, 3], {}]返回结果 -1sub(2, 3) = -1 实现RPC的一个比较复杂的问题是如何去处理异常。至少，当方法产生异常时服务器不应该奔溃。因此，返回给客户端的异常所代表的含义就要好好设计了。 如果使用pickle，异常对象实例在客户端能被反序列化并抛出。如果使用其他的协议，那得想想另外的方法了。不过至少，应该在响应中返回异常字符串。在JSON的例子中就是使用的这种方式。 博文内容参考 《Python Cookbook》 What is WSGI?:https://wsgi.readthedocs.io/en/latest/what.html PEP 3333 - Python Web 服务器网关接口 v1.0.1:https://peps.python.org/pep-3333/

