&quot; + bodyHash + &quot;
&quot;; } /** * 计算请求报文的哈希值 * @param request * @return * @throws IOException * @throws NoSuchAlgorithmException */ private String getBodyHash(String request) throws IOException, NoSuchAlgorithmException { MessageDigest md = MessageDigest.getInstance(&quot;SHA-1&quot;); md.update(request.getBytes()); byte[] hash = md.digest(); return Hex.encodeHexString(hash); } /** * 计算给定字符串（str）基于指定密钥（key）的HMAC - SHA256值 * @param str * @param key * @return * @throws Exception */ private String toHMAC_SHA256(String str, String key) throws Exception { byte[] secret = key.getBytes(StandardCharsets.UTF_8); SecretKeySpec secretKey = new SecretKeySpec(secret, &quot;HmacSHA256&quot;); Mac mac = Mac.getInstance(secretKey.getAlgorithm()); mac.init(secretKey); byte[] macData = mac.doFinal(str.getBytes(StandardCharsets.UTF_8)); byte[] hex = (new Hex()).encode(macData); return new String(hex, StandardCharsets.UTF_8); } /** * 获取请求报文数据， * @param request * @return * @throws IOException * todo 需要注意 `request.getInputStream()` 只能读一次 */ public static String getRequestBody(HttpServletRequest request) throws IOException { StringBuilder stringBuilder = new StringBuilder(); ServletInputStream inputStream = null; BufferedReader bufferedReader = null; try { inputStream = request.getInputStream(); bufferedReader = new BufferedReader(new InputStreamReader(inputStream, &quot;UTF-8&quot;)); char[] charBuffer = new char[128]; int bytesRead; while ((bytesRead = bufferedReader.read(charBuffer)) != -1) { stringBuilder.append(charBuffer, 0, bytesRead); } } finally { if (bufferedReader != null) { bufferedReader.close(); } if (inputStream != null) { inputStream.close(); } } return stringBuilder.toString(); } /** * 响应报文的二次封装处理 */ private static class EncryptingResponseWrapper extends HttpServletResponseWrapper { private ByteArrayOutputStream outputStream = new ByteArrayOutputStream(); private PrintWriter writer = new PrintWriter(outputStream); public EncryptingResponseWrapper(HttpServletResponse response) { super(response); } @Override public ServletOutputStream getOutputStream() throws IOException { return new EncryptingServletOutputStream(outputStream); } @Override public PrintWriter getWriter() throws IOException { return writer; } public String getResponseData() throws IOException { writer.flush(); return outputStream.toString(StandardCharsets.UTF_8.name()); } } private static class EncryptingServletOutputStream extends ServletOutputStream { private final ByteArrayOutputStream byteArrayOutputStream; public EncryptingServletOutputStream(ByteArrayOutputStream byteArrayOutputStream) { this.byteArrayOutputStream = byteArrayOutputStream; } @Override public void write(int b) throws IOException { byteArrayOutputStream.write(b); } @Override public void write(byte[] b) throws IOException { byteArrayOutputStream.write(b); } @Override public void write(byte[] b, int off, int len) throws IOException { byteArrayOutputStream.write(b, off, len); } @Override public void flush() throws IOException { byteArrayOutputStream.flush(); } @Override public void close() throws IOException { byteArrayOutputStream.close(); } @Override public boolean isReady() { return false; } @Override public void setWriteListener(WriteListener writeListener) { } } /** * 请求报文的二次封装处理 */ public class CustomHttpServletRequestWrapper extends HttpServletRequestWrapper { private final ServletInputStream inputStream; // 构造器接受 HttpServletRequest 和请求体字节数组 public CustomHttpServletRequestWrapper(HttpServletRequest request, byte[] body) throws IOException { super(request); this.inputStream = new ByteArrayServletInputStream(body); } @Override public ServletInputStream getInputStream() throws IOException { // 返回自定义的 ByteArrayInputStream，读取请求体内容 return inputStream; } // 如果需要也可以重写 getReader() 方法，以便读取请求体作为字符流 } public class ByteArrayServletInputStream extends ServletInputStream { private final ByteArrayInputStream byteArrayInputStream; public ByteArrayServletInputStream(byte[] data) { this.byteArrayInputStream = new ByteArrayInputStream(data); } @Override public int read() throws IOException { return byteArrayInputStream.read(); } @Override public int read(byte[] b) throws IOException { return byteArrayInputStream.read(b); } @Override public long skip(long n) throws IOException { return byteArrayInputStream.skip(n); } @Override public int available() throws IOException { return byteArrayInputStream.available(); } @Override public void close() throws IOException { byteArrayInputStream.close(); } @Override public synchronized void mark(int readlimit) { byteArrayInputStream.mark(readlimit); } @Override public synchronized void reset() throws IOException { byteArrayInputStream.reset(); } @Override public boolean markSupported() { return byteArrayInputStream.markSupported(); } @Override public boolean isFinished() { return false; } @Override public boolean isReady() { return false; } @Override public void setReadListener(ReadListener readListener) { } }} 博文部分内容参考© 文中涉及参考链接内容版权归原作者所有，如有侵权请告知 :) © 2018-至今 liruilonger@gmail.com, 保持署名-非商用-相同方式共享(CC BY-NC-SA 4.0)

我看远山，远山悲悯 写在前面 博文内容涉及 LangChain 模型IO 模块认知 以及 模型包装器，提示词模版，输出解析器认知以及Demo 理解不足小伙伴帮忙指正 :),生活加油 我看远山，远山悲悯 持续分享技术干货，感兴趣小伙伴可以关注下 ^_^ Lang Chain 模块认知 模型 IOLang Chain 是在 LLM 爆发之后，最早有一定知名度的开源工具，其他生态大部分工具也都基于 Lang Chain 的架构方式，所以通过学习 Lang Chain 可以了解 大部分的 AI 应用工具，今天和小伙伴分享 Lang Chain 模块中的 模型 IO 模型 I/O 模块作为 LangChain 框架的核心组件，通过封装 50 余种大语言模型的 API 接口，构建了跨平台的统一交互范式。 其核心设计目标在于屏蔽底层 API 差异（如 OpenAI 的文本补全接口与智谱清言的聊天式接口差异），使开发者仅需通过标准化的 LLM 和 ChatModel 包装器类即可调用各类模型。 这种抽象机制不仅支持云端最新模型（如 GPT-4、DeepSeek-R1）的无缝接入，还能快速集成本地部署的开源模型（通过 Ollama 加载）或 HuggingFace 社区模型，开发者仅需调整初始化参数即可完成模型切换，无需重写业务逻辑代码。 通过 PromptTemplate 标准化输入格式、OutputParser 结构化输出结果，该模块将复杂的 API 调用协议简化为 3-5 行代码即可完成的标准化流程，真正实现了”一次编码，多模型适配“的开发体验 模型IO 的核心功能： 模型包装器:通过接口调用大语言模型 提示词模板管理:将输入进行模板化，并动态地选择和管理这些模板 输出解析器:从模型输出中提取信息 下面我们依次看一下这三块内容 模型包装器模型包装器分类： LLM 模型包装器: 通用的 LLM 模型包装器（返回值为 串）from langchain_community.llms import Ollama 聊天模型包装器: 专门针对聊天类型API的聊天模型(聊天模型包装器)(返回值为 AIMesssage)from langchain_community.chat_models import ChatOllama 分别来看一下 LLM 模型包装器LLM模型包装器 通过 langchain_community.llms 获取的模型包装器（如 OpenAI 等）均为 BaseLLM 的子类，它们通过继承统一基类的方法与属性，实现了对50余种大语言模型（如 OpenAI 的 text-davinci-003、Llama.cpp 本地模型）API 的标准化封装。 开发者仅需调用 invoke 或 generate 方法即可完成文本补全、代码生成等任务，无需关注底层 API 的差异化调用协议（如 OpenAI 的文本补全接口与智谱清言的聊天式接口差异）。此类包装器尤其适用于自由文本生成场景（如文案创作、代码续写），并通过 PromptTemplate 实现输入模板化，显著降低多模型切换的代码改造成本。 下面为一个 LLM 模型包装器的Demo 12345678910111213141516171819202122232425262728293031323334#!/usr/bin/env python# -*- encoding: utf-8 -*-&quot;&quot;&quot;@File : demo.py@Time : 2025/03/09 01:13:15@Author : Li Ruilong@Version : 1.0@Contact : liruilonger@gmail.com@Desc : LangChain Demo&quot;&quot;&quot;# here put the import lib#pip install langchain langchain-community ollama -i https://pypi.tuna.tsinghua.edu.cn/simplefrom langchain_community.llms import Ollama# 初始化 Ollama 连接llm = Ollama( base_url=&quot;http://localhost:11434&quot;, # Ollama 默认端口 model=&quot;deepseek-r1:latest&quot;, temperature=0.3, # 控制创造性（0-1） num_ctx=4096 # 上下文长度)# 单次对话response = llm.invoke(&quot;LLM 是什么？&quot;)print(&quot;回答：&quot;, response)print(&quot;===========================================================&quot;)# 流式输出（适合长文本）for chunk in llm.stream(&quot;LLM 如何学习？&quot;): print(chunk, end=&quot;&quot;, flush=True) 聊天模型包装器聊天模型包装器 langchain_community.chat_models 提供的聊天模型包装器（如 ChatOpenAI、ChatAnthropic）专为多轮对话场景设计，通过结构化消息类型（SystemMessage、HumanMessage、AIMessage）实现对话状态管理。 此类包装器适配 GPT-4、DeepSeek-R1 等先进模型的 Chat 类型 API，支持以消息列表作为输入（例如系统角色设定+用户提问），并返回 AIMessage 类型的结构化响应。 其核心优势在于简化复杂对话逻辑的开发流程，例如客服机器人需维护的上下文记忆（Memory 模块）与多轮意图理解，开发者可通过 LLMChain 将聊天模型与提示词模板、输出解析器无缝串联，实现“对话即代码”的高效开发范式 聊天模型包装器Demo 123456789101112131415161718192021222324252627282930313233343536373839404142#!/usr/bin/env python# -*- encoding: utf-8 -*-&quot;&quot;&quot;@File : demo_prompt.py@Time : 2025/03/09 04:06:14@Author : Li Ruilong@Version : 1.0@Contact : liruilonger@gmail.com@Desc : None&quot;&quot;&quot;# here put the import libfrom langchain_core.prompts import FewShotPromptTemplate, PromptTemplatefrom langchain_community.chat_models import ChatOllamafrom langchain_community.llms import Ollamafrom langchain_core.prompts import ChatPromptTemplate, HumanMessagePromptTemplate# 初始化 Ollama 连接llm = Ollama( base_url=&quot;http://localhost:11434&quot;, # Ollama 默认端口 model=&quot;deepseek-r1:latest&quot;, temperature=0.3, # 控制创造性（0-1） num_ctx=4096 # 上下文长度)# 配置本地模型chat_model = ChatOllama(model=&quot;deepseek-r1:latest&quot;)chat_template = ChatPromptTemplate.from_messages([ (&quot;system&quot;, &quot;你是一位唐诗研究专家，用中文回答时保持古典韵味&quot;), (&quot;human&quot;, &quot;请赏析{poem_title}的意境&quot;), (&quot;ai&quot;, &quot;好的，我将从以下三个方面分析：
1. 意象运用
2. 情感表达
3. 历史背景&quot;), (&quot;human&quot;, &quot;{user_question}&quot;)])messages = chat_template.format_messages( poem_title=&quot;《登鹳雀楼》&quot;, user_question=&quot;诗中'更上一层楼'有何哲学深意？&quot;)for msg in messages: print(chat_model.invoke(messages)) 提示词模板提示词模板（PromptTemplate）是AI交互中的结构化生成工具，其本质是通过预定义模板字符串（含占位符）动态生成适配场景的提示词。 例如，使用{变量}占位符可将用户输入、任务指令、示例数据等元素动态注入模板，实现“一次设计，多次复用”的工程化开发模式,其核心价值在于将复杂提示逻辑抽象为标准化的代码组件，开发者可通过调整输入变量（如input_variables=[&quot;style&quot;,&quot;topic&quot;]）快速切换任务场景，无需重写底层逻辑。 提示词模板的三层结构化设计 ​指令层（Instruction Layer）​ 明确的指令定义任务目标与执行规则，例如 “你是一名数据科学家，请用时间序列模型预测销售额”即为典型指令。此类指令通过角色设定（role）、任务说明（task）和格式约束（如“输出表格”），强制对齐模型输出与业务需求。 ​示例层（Few-shot Layer） 少量示例（Few-shot Learning）可显著提升模型理解能力。例如通过投喂“SPD项目需求描述+预期输出框架”的示例对，引导模型生成符合行业规范的方案。这种“输入-输出”示例对可视为模板中的静态知识库，用于激活模型的类比推理能力。 ​动态输入层（Dynamic Input Layer） 用户输入变量（如topic=”人工智能”）作为模板的动态参数，决定生成内容的细粒度。比如 社团活动策划案例中，“预算限制”“目标人群”等变量被注入模板，使AI输出的策划案兼具通用框架与个性化细节。支持链式调用，例如通过LLMChain串联多个模板实现多轮对话。 从技术实现看，提示词模板常封装为可复用类，其核心方法包括： 变量声明：通过input_variables定义占位符参数类型； 模板加载：支持从外部文件读取模板，实现代码与内容分离； 格式控制：强制输出结构化内容（如Markdown表格、JSON），降低后续数据解析成本 下面我们看一些常见的模版 基础提示模板 (PromptTemplate)单变量，多变量带格式控制 12345678910111213141516171819202122232425262728293031323334353637383940414243444546#!/usr/bin/env python# -*- encoding: utf-8 -*-&quot;&quot;&quot;@File : demo_prompt.py@Time : 2025/03/09 04:06:14@Author : Li Ruilong@Version : 1.0@Contact : liruilonger@gmail.com@Desc : None&quot;&quot;&quot;# here put the import libfrom langchain_core.prompts import PromptTemplatefrom langchain_community.llms import Ollama# 初始化 Ollama 连接llm = Ollama( base_url=&quot;http://localhost:11434&quot;, # Ollama 默认端口 model=&quot;deepseek-r1:latest&quot;, temperature=0.3, # 控制创造性（0-1） num_ctx=4096 # 上下文长度)# 单变量模板simple_template = &quot;&quot;&quot;你是一个资深{role}，请用中文回答：问题：{question}答案：&quot;&quot;&quot;prompt = PromptTemplate.from_template(simple_template)print(prompt.format(role=&quot;算法工程师&quot;, question=&quot;如何优化快速排序？&quot;))chain = llmprint(chain.invoke(prompt.format(role=&quot;算法工程师&quot;, question=&quot;如何优化快速排序？&quot;)))# 多变量带格式控制advanced_template = PromptTemplate( input_variables=[&quot;language&quot;, &quot;task&quot;], template=&quot;&quot;&quot; 请用{language}编写一个{task}的代码示例， 要求包含详细的注释和异常处理。 &quot;&quot;&quot;)print(chain.invoke(advanced_template.format(language=&quot;Python&quot;, task=&quot;文件读写操作&quot;)))) 少量示例模板 (FewShotPromptTemplate)顾名思义，在推理前提供几个推理Demo，我们在最开始也讲到这种提示模版 123456789101112131415161718192021222324252627282930313233343536# here put the import libfrom langchain_core.prompts import FewShotPromptTemplate, PromptTemplatefrom langchain_community.llms import Ollama# 初始化 Ollama 连接llm = Ollama( base_url=&quot;http://localhost:11434&quot;, # Ollama 默认端口 model=&quot;deepseek-r1:latest&quot;, temperature=0.3, # 控制创造性（0-1） num_ctx=4096 # 上下文长度)# 示例数据集examples = [ {&quot;input&quot;: &quot;高兴&quot;, &quot;output&quot;: &quot;笑容如春风拂面，眼中闪烁着星辰般的光芒&quot;}, {&quot;input&quot;: &quot;悲伤&quot;, &quot;output&quot;: &quot;眼角低垂似凋零的花瓣，双肩微微颤动如秋叶飘零&quot;}]# 单个示例模板example_template = &quot;&quot;&quot;输入情感：{input}文学化描述：{output}&quot;&quot;&quot;# 构建完整模板few_shot_prompt = FewShotPromptTemplate( examples=examples, example_prompt=PromptTemplate( input_variables=[&quot;input&quot;, &quot;output&quot;], template=example_template ), suffix=&quot;请将以下情感转化为文学描述：
情感：{input}&quot;, input_variables=[&quot;input&quot;])print(llm.invoke(few_shot_prompt.format(input=&quot;愤怒&quot;))) 聊天提示模板 (ChatPromptTemplate)聊天提示模版，ChatPromptTemplate 能整合不同角色的消息（系统、用户、AI），形成连贯的对话上下文 123456789101112131415161718192021222324252627282930313233343536373839404142#!/usr/bin/env python# -*- encoding: utf-8 -*-&quot;&quot;&quot;@File : demo_prompt.py@Time : 2025/03/09 04:06:14@Author : Li Ruilong@Version : 1.0@Contact : liruilonger@gmail.com@Desc : None&quot;&quot;&quot;# here put the import libfrom langchain_core.prompts import FewShotPromptTemplate, PromptTemplatefrom langchain_community.chat_models import ChatOllamafrom langchain_community.llms import Ollamafrom langchain_core.prompts import ChatPromptTemplate, HumanMessagePromptTemplate# 初始化 Ollama 连接llm = Ollama( base_url=&quot;http://localhost:11434&quot;, # Ollama 默认端口 model=&quot;deepseek-r1:latest&quot;, temperature=0.3, # 控制创造性（0-1） num_ctx=4096 # 上下文长度)# 配置本地模型chat_model = ChatOllama(model=&quot;deepseek-r1:latest&quot;)chat_template = ChatPromptTemplate.from_messages([ (&quot;system&quot;, &quot;你是一位唐诗研究专家，用中文回答时保持古典韵味&quot;), (&quot;human&quot;, &quot;请赏析{poem_title}的意境&quot;), (&quot;ai&quot;, &quot;好的，我将从以下三个方面分析：
1. 意象运用
2. 情感表达
3. 历史背景&quot;), (&quot;human&quot;, &quot;{user_question}&quot;)])messages = chat_template.format_messages( poem_title=&quot;《登鹳雀楼》&quot;, user_question=&quot;诗中'更上一层楼'有何哲学深意？&quot;)for msg in messages: print(chat_model.invoke(messages)) 组合模板 (PipelinePromptTemplate)PipelinePromptTemplate 是 LangChain 框架中用于组合复杂提示词流程的核心工具，特别适用于需要分阶段处理或多模块协作的场景。以下是其核心特性与用法详解 123456789101112131415161718192021222324252627282930313233343536373839404142434445464748#!/usr/bin/env python# -*- encoding: utf-8 -*-&quot;&quot;&quot;@File : demo_prompt.py@Time : 2025/03/09 04:06:14@Author : Li Ruilong@Version : 1.0@Contact : liruilonger@gmail.com@Desc : None&quot;&quot;&quot;# here put the import libfrom langchain_core.prompts import PromptTemplatefrom langchain_community.llms import Ollamafrom langchain_core.prompts import PipelinePromptTemplate# 初始化 Ollama 连接llm = Ollama( base_url=&quot;http://localhost:11434&quot;, # Ollama 默认端口 model=&quot;deepseek-r1:latest&quot;, temperature=0.3, # 控制创造性（0-1） num_ctx=4096 # 上下文长度)# 基础模板base_template = &quot;&quot;&quot;{concept}（{year}年提出）的核心思想是：{summary}&quot;&quot;&quot;# 详细说明模板detail_template = &quot;&quot;&quot;请用中文分点说明{concept}：1. 基本定义2. 主要应用场景3. 最新发展（截至{year}）&quot;&quot;&quot;combined_prompt = PipelinePromptTemplate( final_prompt=PromptTemplate.from_template(base_template), pipeline_prompts=[ (&quot;summary&quot;, PromptTemplate.from_template(detail_template)) ])print(llm.invoke(combined_prompt.format( concept=&quot;注意力机制&quot;, year=2023))) 自定义模板 (Custom Template)通过继承StringPromptTemplate 实习动态模版参数 12345678910111213141516171819202122232425from langchain_core.prompts import StringPromptTemplatefrom pydantic import BaseModelclass CodePrompt(BaseModel): language: str framework: str = &quot;无框架&quot;class CodeTemplate(StringPromptTemplate): def format(self, **kwargs) -&gt; str: prompt = f&quot;&quot;&quot; # 代码生成助手 语言：{kwargs['language']} 框架：{kwargs.get('framework', '标准库')} 功能需求：{kwargs['requirement']} 附加要求：{kwargs.get('constraint', '无')} &quot;&quot;&quot; return prompt.replace(&quot; &quot;, &quot;&quot;) # 清理缩进template = CodeTemplate(input_variables=[&quot;language&quot;, &quot;framework&quot;, &quot;requirement&quot;])print(template.format( language=&quot;Python&quot;, framework=&quot;FastAPI&quot;, requirement=&quot;创建文件上传接口&quot;, constraint=&quot;限制文件大小为10MB&quot;)) 文件加载模板 (load_prompt)类似运维剧本中的 模版文件，熟悉 Ansible 的小伙伴对这个应该不陌生 123456789101112131415# 创建模板文件 prompt.yaml&quot;&quot;&quot;_type: promptinput_variables: [&quot;country&quot;]template: 请用中文介绍{country}的： 1. 历史沿革 2. 文化特色 3. 现代发展&quot;&quot;&quot;from langchain_core.prompts import load_promptloaded_prompt = load_prompt(&quot;prompt.yaml&quot;)print(loaded_prompt.format(country=&quot;意大利&quot;)) 模板选择参考 模板类型 适用场景 优势 PromptTemplate 简单问答、代码生成 快速构建基础提示 ChatPromptTemplate 对话系统 支持多角色消息 FewShotPromptTemplate 需要示例引导的任务 提升模型输出一致性 PipelinePromptTemplate 复杂逻辑分解 实现提示的模块化组合 自定义模板 特殊格式要求 完全控制提示结构 通过组合这些模板，可以构建适应各种复杂场景的提示工程系统。建议根据具体任务复杂度选择适当模板，必要时结合 LangChain Expression Language 构建工作流。 输出解析器输出解析器，顾名思义将模型生成的输出格式转化为可以在代码中直接使用的格式。对于这个问题，通常使用LangChain 的输出解析器(OutputParsers)工具来解决 使用 LangChain 输出解析器（Output Parsers）的常见场景 Demo 示例，涵盖结构化数据、JSON、列表等格式的自动转换： 基础解析器：Pydantic 模型结构化输出将 LLM 输出转换为符合预定义结构的 Python 对象 123456789101112131415161718192021222324252627282930313233343536373839404142from langchain_core.pydantic_v1 import BaseModel, Fieldfrom langchain_core.output_parsers import PydanticOutputParser# 1. 定义数据结构模型class Book(BaseModel): title: str = Field(description=&quot;书名&quot;) author: str = Field(description=&quot;作者&quot;) year: int = Field(description=&quot;出版年份&quot;) genres: list[str] = Field(description=&quot;书籍分类&quot;)# 2. 创建解析器parser = PydanticOutputParser(pydantic_object=Book)# 3. 自动生成格式指令（注入提示词）format_instructions = parser.get_format_instructions()print(format_instructions)# 输出示例：# &quot;请用以下JSON格式输出...属性包括 title, author, year, genres...&quot;# 4. 组合提示词模板from langchain_core.prompts import PromptTemplateprompt = PromptTemplate( template=&quot;请根据描述生成书籍信息：{query}
{format_instructions}&quot;, input_variables=[&quot;query&quot;], partial_variables={&quot;format_instructions&quot;: format_instructions},)from langchain_community.llms import Ollamallm = Ollama( base_url=&quot;http://localhost:11434&quot;, # Ollama 默认端口 model=&quot;deepseek-r1:latest&quot;, temperature=0.3, # 控制创造性（0-1） num_ctx=4096 # 上下文长度)# 5. 调用模型并解析chain = prompt | llm | parserresult = chain.invoke({&quot;query&quot;: &quot;鲁迅的第一本小说集&quot;})print(type(result)) # &lt;class '__main__.Book'&gt;print(result.title) # 《呐喊》 JSON 格式解析器直接解析模型返回的 JSON 字符串为 Python 字典 123456789101112131415161718192021222324252627from langchain_core.output_parsers import JsonOutputParser# 1. 定义解析器parser = JsonOutputParser()# 2. 提示词模板（自动包含JSON格式要求）prompt = PromptTemplate( template=&quot;生成包含姓名、年龄和兴趣的用户信息：{input}
{format_instructions}&quot;, input_variables=[&quot;input&quot;], partial_variables={&quot;format_instructions&quot;: parser.get_format_instructions()},)from langchain_community.llms import Ollamallm = Ollama( base_url=&quot;http://localhost:11434&quot;, # Ollama 默认端口 model=&quot;deepseek-r1:latest&quot;, temperature=0.3, # 控制创造性（0-1） num_ctx=4096 # 上下文长度)# 3. 调用并解析,通过表达式的方式chain = prompt | llm | parserdata = chain.invoke({&quot;input&quot;: &quot;一个热爱AI的00后开发者&quot;})print(data)# 输出示例：# {'name': '张晓明', 'age': 24, 'interests': ['人工智能', '编程']} 列表解析器将模型输出的无序文本转换为有序列表 12345678910111213141516171819202122232425from langchain_core.output_parsers import CommaSeparatedListOutputParserparser = CommaSeparatedListOutputParser()format_instructions = parser.get_format_instructions() # &quot;用逗号分隔的列表&quot;prompt = PromptTemplate( template=&quot;列举5个{theme}相关的关键技术：
{format_instructions}&quot;, input_variables=[&quot;theme&quot;], partial_variables={&quot;format_instructions&quot;: format_instructions},)from langchain_community.llms import Ollamallm = Ollama( base_url=&quot;http://localhost:11434&quot;, # Ollama 默认端口 model=&quot;deepseek-r1:latest&quot;, temperature=0.3, # 控制创造性（0-1） num_ctx=4096 # 上下文长度)chain = prompt | llm | parsertech_list = chain.invoke({&quot;theme&quot;: &quot;自动驾驶&quot;})print(tech_list)# 输出示例：# ['激光雷达', '计算机视觉', '高精地图', '路径规划', 'V2X通信'] 结构化文本解析器提取文本中的关键字段（类似键值对） 123456789101112131415161718192021222324252627282930313233from langchain_core.output_parsers import StructuredOutputParser, ResponseSchema# 1. 定义响应字段response_schemas = [ ResponseSchema(name=&quot;company&quot;, description=&quot;公司名称&quot;), ResponseSchema(name=&quot;industry&quot;, description=&quot;所属行业&quot;), ResponseSchema(name=&quot;revenue&quot;, description=&quot;年营收（单位：亿元）&quot;, type=&quot;float&quot;),]# 2. 创建解析器parser = StructuredOutputParser.from_response_schemas(response_schemas)format_instructions = parser.get_format_instructions()# 3. 组合提示词prompt = PromptTemplate( template=&quot;分析以下企业：{text}
{format_instructions}&quot;, input_variables=[&quot;text&quot;], partial_variables={&quot;format_instructions&quot;: format_instructions},)from langchain_community.llms import Ollamallm = Ollama( base_url=&quot;http://localhost:11434&quot;, # Ollama 默认端口 model=&quot;deepseek-r1:latest&quot;, temperature=0.3, # 控制创造性（0-1） num_ctx=4096 # 上下文长度)# 4. 执行解析chain = prompt | llm | parseroutput = chain.invoke({&quot;text&quot;: &quot;华为2023年营收超过7000亿元&quot;})print(output)# {'company': '华为', 'industry': '信息与通信技术', 'revenue': 7000.0} 日期时间解析器自动解析文本中的日期时间 1234567891011121314151617181920212223from langchain.output_parsers import DatetimeOutputParserparser = DatetimeOutputParser()format_instructions = parser.get_format_instructions() # 要求输出ISO 8601格式prompt = PromptTemplate( template=&quot;将以下日期转换为标准格式：{date}
{format_instructions}&quot;, input_variables=[&quot;date&quot;], partial_variables={&quot;format_instructions&quot;: format_instructions},)from langchain_community.llms import Ollamallm = Ollama( base_url=&quot;http://localhost:11434&quot;, # Ollama 默认端口 model=&quot;deepseek-r1:latest&quot;, temperature=0.3, # 控制创造性（0-1） num_ctx=4096 # 上下文长度)chain = prompt | llm | parserresult = chain.invoke({&quot;date&quot;: &quot;明年端午节&quot;})print(result.strftime(&quot;%Y-%m-%d&quot;)) # 2025-05-31（假设当前是2024年） 自动重试解析器当解析失败时自动重试 123456789101112from langchain.output_parsers import RetryOutputParser# 包裹基础解析器（以JSON为例）base_parser = JsonOutputParser()parser = RetryOutputParser.from_llm(parser=base_parser, llm=llm)# 使用示例（当第一次解析失败时自动调整提示）try: data = parser.parse(&quot;非标准回答：{name: 'AI助手'}&quot;)except: # 自动触发重试逻辑 fixed_data = parser.parse_with_prompt(&quot;...&quot;, original_prompt) 通过组合不同的输出解析器，可以轻松实现从自由文本到程序可消费数据结构的无缝衔接。具体选择取决于业务场景是否需要强结构（Pydantic）、弱结构（JSON）或简单列表等格式。 博文部分内容参考© 文中涉及参考链接内容版权归原作者所有，如有侵权请告知 :) https://python.langchain.com/docs/ 《LangChain 入门指南构建高可复用、可扩展的 LLM 应用程序》 © 2018-至今 liruilonger@gmail.com, 保持署名-非商用-相同方式共享(CC BY-NC-SA 4.0)

我看远山，远山悲悯 写在前面 博文内容为 LangChain + Ollama + DeepSeek 本地部署 LLM 应用开发认知 涉及 LangChain 架构，核心模块认知 以及 模型包装器，提示词模版，Agent 方式开发AI应用 Demo 理解不足小伙伴帮忙指正 :),生活加油 我看远山，远山悲悯 持续分享技术干货，感兴趣小伙伴可以关注下 ^_^ lang Chain 基本认知在开源项目中，它这样介绍自己： LangChain 是一个用于开发由大型语言模型(LLMs)驱动的应用程序的框架。对于这些应用，LangChain 简化了整个应用生命周期: 开源库: 使用 LangChain 的开源组件和第三方集成构建您的应用程序。使用 LangGraph 构建具有流处理和人机交互支持的带状态代理。 生产化: 使用 LangSmith 检查、监控和评估您的应用程序，以便您可以不断进行优化并充满信心地进行部署。 部署: 使用 LangGraph 平台将您的 LangGraph 应用程序转换为生产就绪的API和助手。LangGraph是一个用于构建具有LLMs的状态和多主体应用程序的库，用于创建代理和多代理工作流。 对应的项目地址： langchain: https://github.com/langchain-ai/langchain langgraph: https://github.com/langchain-ai/langgraph langsmith: https://github.com/langchain-ai/langsmith-sdk 这里我们只关注 langchain ，langgraph 和 langsmith 在之后的博文和小伙伴分享 Lang Chain 应用场景： 问答系统，数据处理与管理，Agent ,RAG 等 lang Chain 架构lang Chain 通过 组件和链提供基础能力，类似我们常常画的流程图，工作流引擎一样。 组件： 组件是一个具有明确功能和用途的单元。 类似流程图中的处理框，组件包括提示工程模版, LLM模型包装器、聊天模型包装器等以及和数据增强相关的一系列工具和接口。可以把它们看作数据处理流水线上的各个工作站。每个组件都有其特定的职责，如处理数据的输入输出、转化数据格式。 链： 链是将各种组件连接在一起，它确保组件之间的无缝集成和在程序运行环境中的高效调用。 Lang Chain 核心模块1.模型 I/O(Model IO) LangChain 提供了与任何大语言模型均适配的模型包装器(模型 I/0 的功能)分为 模型包装器（LLM） 和聊天模型包装器(Chat Model)。 LangChain 自身并不提供大语言模型而是提供统一的模型接口。模型包装器这种包装方式允许开发者与不同模型平台底层的 API进行交互，从而简化了大语言模型的调用，降低了开发者的学习成本。此外，其输出解析器也能帮助开发者从模型输出中提取所需的信息。 模型包装器的提示词模板功能使得开发者可以模板化、动态选择和管理模型输人 2.数据增强(Data Connection) 许多LLM 应用需要的用户特定数据并不在模型的训练集中。LangChain 提供了加载、转换、存储和査询数据的构建块。开发者可以利用文档加载器从多个来源加载文档，通过文档转换器进行文档切割、转换等操作。矢量存储和数据检索工具则提供了对嵌人数据的存储和查询功能。 3.链( Chain) 单独使用LLM 对于简单应用可能是足够的，但面对复杂的应用往往需要将多个 LLM 模型包装器或其他组件进行链式连接。LangChain 为此类链式应用提供了接口。 有点类似于设计模式中的构建者，按需 build ，每次都返回实例本身 4.记忆(Memory) LangChain 提供了多种工具帮助开发者为系统添加记忆功能。记忆功能可以独立使用，也可以无缝集成到链中。记忆模块需要支持两个基本操作，即读取和写入。 在每次运行中，链首先从记忆模块中读取数据，然后在执行核心逻辑后将当前运行的输人和输出写入记忆模块，以供未来引用。通俗的讲，就是会申请一块内存存房历史会话数据。 5.Agent 核心思想是利用LLM 选择操作序列。即把之后的组件调用的决策权交给 LLM，在链中，操作序列是硬编码的,而在代理(Agent)代理中，大语言模型被用作推理引擎，确定执行哪些操作，以及它们的执行顺序。 6.回调处理器(Callback) LangChain 提供了一个回调系统，允许开发者在LLM应用的各个阶段对状态进行干预。这对于日志记录、监视、流处理等任务非常有用。通过API提供的回调参数，开发者可以订阅这些事件。 Demo 实战理论学了那么多，我看几个简单的Demo 认识一下。 