&quot;.join(quotes_db.get(book_title, [&quot;暂未收录该作品语录&quot;]))# 配置本地模型llm = Ollama(model=&quot;deepseek-r1:latest&quot;, temperature=0.3)chat_model = ChatOllama(model=&quot;deepseek-r1:latest&quot;)# 初始化记忆系统memory = ConversationBufferWindowMemory( memory_key=&quot;chat_history&quot;, k=5, return_messages=True)# 构建定制化工具集tools = [ Tool( name=&quot;LiteratureSearch&quot;, func=lambda query: BookQuotesTool.search_quotes(&quot;素履之往&quot;), description=&quot;用于检索木心《素履之往》的经典语录&quot; ), WikipediaQueryRun( api_wrapper=WikipediaAPIWrapper(top_k_results=1, lang=&quot;zh&quot;) )]# 创建带文学分析能力的Agentagent = initialize_agent( tools, chat_model, agent=AgentType.CHAT_CONVERSATIONAL_REACT_DESCRIPTION, memory=memory, verbose=True, handle_parsing_errors=True, max_iterations=3 # 限制搜索深度)# 测试用例queries = [ &quot;列举《素履之往》中关于时间的哲理语句&quot;, &quot;这本书里如何阐述生命的意义？&quot;, &quot;将第二句语录用英文翻译&quot;]for q in queries: print(f&quot;问题：{q}&quot;) print(agent.run(q)) print(&quot;
